import math
import itertools
from functools import reduce

def task_func(numbers):
    total = 0.0

    for length in range(1, len(numbers) + 1):
        for combo in itertools.combinations(numbers, length):
            product = reduce(lambda a, b: a * b, combo, 1)
            total += math.log(product)

    return float(total)
